+fn boundary_up_moves_every_queued_message_into_the_draft() {
+    let mut app = App::default();
+    app.set_mode(Mode::Live);
+    app.plugins.enabled = false;
+    let cwd = std::path::Path::new(".");
+    app.submit("active", cwd);
+    let active = app.request.take().unwrap();
+    app.submit("Check the tests", cwd);
+    app.submit("Also check formatting", cwd);
+    assert!(render(&mut app, 100, 30).contains("Press up to edit queued messages"));
+    paste(&mut app, "Focus on the launcher");
+    key(&mut app, KeyCode::Left);
+    let cursor = app.draft.cursor;
+    key(&mut app, KeyCode::Up);
+    let prefix = "Check the tests\nAlso check formatting\n";
+    assert_eq!(app.draft.text, format!("{prefix}Focus on the launcher"));
+    assert_eq!(app.draft.cursor, prefix.len() + cursor);
+    // Down never puts the retrieved messages back in the queue, and the
+    // finished turn has nothing left to run.
+    key(&mut app, KeyCode::End);
+    key(&mut app, KeyCode::Down);
+    app.apply_update(Update::Finished {
+        id: active.id,
+        result: Err("stopped".into()),
+    });
+    assert!(app.request.is_none());
+    assert_eq!(app.draft.text, format!("{prefix}Focus on the launcher"));
+    assert!(!render(&mut app, 100, 30).contains("Press up to edit queued messages"));
+}
